			dc.l p_addto_r

; ============================================================
; function fact (turbo mode)
; ============================================================

p_fact:

			; 199: Dim r As Long

			; 200: r = 1
			dc.l kw_l_mov, llit_1, var_fact_r

			; 201: Do While k > 1
do10_t:
			dc.l kw_scpgtvl, var_fact_k, 1
			dc.l kw_goto_iffalse, do10_e

			; 202: r = r * k
			dc.l kw_l_itol, var_fact_k, ltmp1
			dc.l kw_l_mul, var_fact_r, ltmp1, var_fact_r

			; 203: k = k - 1
			dc.l kw_dec, var_fact_k

			; 204: Loop
			dc.l do10_t_go
do10_e:

			; 205: Fact = r
			dc.l kw_l_mov, var_fact_r, var_fact_fact
			dc.l p_fact_r

