;## kw_goto_iffalse
;kw_goto_iffalse, <label>  - branch if NZ (false)
kw_goto_iffalse:
			bne kw_gif_go
			addq.l #4, sp
			rts
kw_gif_go:
			movea.l (sp), sp
			rts

			even
;## kw_goto_iftrue
;kw_goto_iftrue, <label>  - branch if Z (true)
kw_goto_iftrue:
			beq kw_git_go
			addq.l #4, sp
			rts
kw_git_go:
			movea.l (sp), sp
			rts

			even
;## ntc_for_jump
; tails for the FOR / NEXT keywords: SP = thread at the label long
ntc_for_take:
			movea.l (sp), sp
			rts
ntc_for_skip:
			addq.l #4, sp
			rts

			even
;## kw_next1l ntc_for_jump
;kw_next1l, <var>, <literal limit>, <toplabel>
;  NEXT for STEP 1: inc var, back to the top while var <= limit (past 32767: ends)
kw_next1l:
			movea.l (sp)+, a0
			move.l (sp)+, d1
			addq.w #1, (a0)
			bvs ntc_for_skip
			cmp.w (a0), d1
			bge ntc_for_take		; limit >= var
			addq.l #4, sp
			rts

			even
;## kw_ltov
;kw_ltov, <literal>, <destvar>
kw_ltov:
			move.l (sp)+, d0
			movea.l (sp)+, a0
			move.w d0, (a0)
			rts

