			addq.b #1, d0
			rts
ntc_lcmp_ge:
			cmp.l d1, d0
			sge d0
			addq.b #1, d0
			rts
ntc_lcmp_ne:
			cmp.l d1, d0
			sne d0
			addq.b #1, d0
			rts

			even
;## kw_l_cplt ntc_lcmp
kw_l_cplt:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			bra ntc_lcmp_lt

			even
;## kw_l_cple ntc_lcmp
kw_l_cple:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			bra ntc_lcmp_le

			even
;## kw_l_cpgt ntc_lcmp
kw_l_cpgt:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			bra ntc_lcmp_gt

			even
;## kw_l_cpge ntc_lcmp
kw_l_cpge:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			bra ntc_lcmp_ge

			even
;## kw_l_cpeq
kw_l_cpeq:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			cmp.l (a1), d0
			rts

			even
;## kw_l_cpne ntc_lcmp
kw_l_cpne:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			bra ntc_lcmp_ne

			even
;## ntc_lmul
; d0.l * d1.l -> d0.l (low 32 bits). jmp (a6). Uses d2, d3
ntc_lmul:
			move.l d0, d2
			move.l d1, d3
			swap d2
			swap d3
			mulu.w d1, d2				; a_hi * b_lo
			mulu.w d0, d3				; a_lo * b_hi
			add.w d3, d2
			swap d2
			clr.w d2
			mulu.w d1, d0				; a_lo * b_lo
			add.l d2, d0
			jmp (a6)

			even
;## ntc_ldiv
; d0.l / d1.l signed, truncating: d0 = quotient, d1 = remainder (the dividend's
; sign). Divide by 0: quotient 0, remainder = dividend. jmp (a6). Uses d2-d5
ntc_ldiv:
			tst.l d1
			bne ntc_ld_nz
			move.l d0, d1
			moveq #0, d0
			jmp (a6)
ntc_ld_nz:
			move.l d0, d4				; the dividend's sign
			move.l d0, d5
			eor.l d1, d5				; the quotient's sign
			tst.l d0
			bpl ntc_ld_ap
			neg.l d0
ntc_ld_ap:
			tst.l d1
			bpl ntc_ld_bp
			neg.l d1
ntc_ld_bp:
			moveq #0, d2				; remainder
			moveq #31, d3
ntc_ld_lp:
			add.l d0, d0
			addx.l d2, d2
			cmp.l d1, d2
			bcs ntc_ld_no
			sub.l d1, d2
			addq.l #1, d0
ntc_ld_no:
			dbra d3, ntc_ld_lp
			tst.l d5
			bpl ntc_ld_qp
			neg.l d0
ntc_ld_qp:
			move.l d2, d1
			tst.l d4
			bpl ntc_ld_rp
			neg.l d1
ntc_ld_rp:
			jmp (a6)

			even
;## kw_l_mul ntc_lmul
kw_l_mul:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			lea kw_lmu_b, a6
			bra ntc_lmul
kw_lmu_b:
			movea.l (sp)+, a0
			move.l d0, (a0)
			rts

			even
;## kw_l_div ntc_ldiv kw_l_mul
kw_l_div:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			lea kw_lmu_b, a6
			bra ntc_ldiv

			even
;## kw_l_mod ntc_ldiv
kw_l_mod:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.l (a0), d0
			move.l (a1), d1
			lea kw_lmd_b, a6
			bra ntc_ldiv
kw_lmd_b:
			movea.l (sp)+, a0
			move.l d1, (a0)
			rts

			even
;## ntc_ltoa ntc_data
; the Long d0 to text at a1, a 0 at the end (a1 on it). jmp (a6). Uses d0-d3, a0
ntc_ltoa:
			tst.l d0
			bpl ntc_lta_pos
			move.b #'-', (a1)+
			neg.l d0
ntc_lta_pos:
			lea ntc_lta_tmp+12, a0
			clr.b -(a0)
ntc_lta_lp:
			; d0 unsigned / 10: high word first
			move.l d0, d2
			clr.w d2
			swap d2
			divu.w #10, d2				; d2 = rem:quot of the high word
			move.w d2, d3				; the quotient's high word
			move.w d0, d2				; rem (high) : low word
			divu.w #10, d2
			swap d3
			move.w d2, d3				; d3 = the quotient
			swap d2
			addi.b #'0', d2
			move.b d2, -(a0)
			move.l d3, d0
			bne ntc_lta_lp
ntc_lta_cp:
			move.b (a0)+, (a1)+
			bne ntc_lta_cp
			subq.l #1, a1
			jmp (a6)

			even
;## kw_l_print ntc_ltoa ntc_printbuf
kw_l_print:
			movea.l (sp)+, a0
			move.l (a0), d0
			lea ntc_numbuf, a1
			lea kw_lpr_b, a6
			bra ntc_ltoa
kw_lpr_b:
			lea ntc_numbuf, a0
			bra ntc_printbuf

			even
;## kw_l_cstr ntc_ltoa
kw_l_cstr:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.l (a0), d0
			lea ntc_next, a6
			bra ntc_ltoa

			even
;## kw_l_str ntc_ltoa
kw_l_str:
			movea.l (sp)+, a1
			movea.l (sp)+, a0
			move.l (a0), d0
			bmi kw_lst_go
			move.b #' ', (a1)+
kw_lst_go:
			lea ntc_next, a6
			bra ntc_ltoa

			even
;## kw_l_val
;kw_l_val, <src>, <destlong>  - Val() to a Long (decimal)
kw_l_val:
			movea.l (sp)+, a0
			movea.l (sp)+, a2
ntc_lv_go:
			moveq #0, d0
			moveq #0, d2
ntc_lv_sp:
			cmpi.b #' ', (a0)
			bne ntc_lv_sg
			addq.l #1, a0
			bra ntc_lv_sp
ntc_lv_sg:
			cmpi.b #'-', (a0)
			bne ntc_lv_dig
			moveq #1, d2
			addq.l #1, a0
ntc_lv_dig:
			moveq #0, d1
			move.b (a0)+, d1
			subi.b #'0', d1
			bcs ntc_lv_done
			cmpi.b #10, d1
			bcc ntc_lv_done
			move.l d0, d3
			add.l d0, d0
			add.l d0, d0
			add.l d3, d0
			add.l d0, d0				; * 10
			add.l d1, d0
			bra ntc_lv_dig
ntc_lv_done:
			tst.w d2
			beq ntc_lv_st
			neg.l d0
ntc_lv_st:
			move.l d0, (a2)
			rts

			even
;## kw_l_aget
;kw_l_aget, <arraybase>, <indexvar>, <dest>  - Long array element
kw_l_aget:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			lsl.l #2, d0
			movea.l (sp)+, a1
			move.l 0(a0, d0.l), (a1)
			rts

			even
;## kw_l_aset
;kw_l_aset, <arraybase>, <indexvar>, <src>  - set a Long array element
kw_l_aset:
			movea.l (sp)+, a0
			movea.l (sp)+, a1
			move.w (a1), d0
			ext.l d0
			lsl.l #2, d0
			movea.l (sp)+, a1
			move.l (a1), 0(a0, d0.l)
			rts

			even
;## kw_bssinit ntc_data ntc_plat_screen
;kw_bssinit, <start>, <size>  - the start of the main thread: the program's arrays live after
;  the RAM variables (not in the ROM). Check they fit under the end of RAM, then clear them.
;  Too big: a message, the program stops.
kw_bssinit:
			movea.l (sp)+, a0
			move.l (sp)+, d0
			andi.l #$FFFF, d0
			move.l a0, d1
			add.l d0, d1
			cmpi.l #$01000000, d1
			bhi kw_bs_big
			tst.l d0
			beq kw_bs_e
kw_bs_lp:
			clr.b (a0)+
			subq.l #1, d0
			bne kw_bs_lp
kw_bs_e:
			rts
kw_bs_big:
			NTC_RS
			lea kw_bs_txt, a2
kw_bs_pl:
			moveq #0, d0
			move.b (a2)+, d0
			beq kw_bs_stop
			jsr ntc_plat_putc
			bra kw_bs_pl
kw_bs_stop:
			jsr ntc_plat_newline
			jmp kw_stop
kw_bs_txt:	dc.b "Not enough memory for the arrays", 0
			even

			even
;## ntc_md_boot ntc_plat_data ntc_data ntc_md_vdp ntc_md_fontdata ntc_plat_screen
; ------------------------------------------------------------
; the start ($200): TMSS, the Z80 held, RAM cleared and the RAM block copied
; from the ROM, the VDP, the font, the pads, the PSG quiet; then user mode
; on the real stack and into ntc_start
; ------------------------------------------------------------
VDP_DATA	equ $C00000
VDP_CTRL	equ $C00004
PSG_PORT	equ $C00011
NTC_USTACK	equ $00FF7800			; the real stack's top
ntc_md_entry:
			move.w #$2700, sr
			move.b $A10001, d0
			andi.b #$0F, d0
			beq ntc_mb_notmss
			move.l #'SEGA', $A14000		; TMSS
ntc_mb_notmss:
			move.w #$0100, $A11100		; the Z80's bus ours
			move.w #$0000, $A11200		; and the Z80 held in reset
			lea $FF0000, a0				; RAM cleared (below the supervisor stack's last words: no)
			move.w #($8000/4)-1, d0
ntc_mb_clr:
			clr.l (a0)+
			dbra d0, ntc_mb_clr
			lea $FF8000, a0
			move.w #($8000/4)-1, d0
ntc_mb_clr2:
			clr.l (a0)+
			dbra d0, ntc_mb_clr2
			lea ntc_romend, a0			; the RAM block's first image, from the ROM
			lea ntc_ram, a1
			move.l #ntc_ramend-ntc_ram, d0
			beq ntc_mb_nodata
ntc_mb_cp:
			move.b (a0)+, (a1)+
			subq.l #1, d0
			bne ntc_mb_cp
ntc_mb_nodata:
			move.w VDP_CTRL, d0			; (the VDP's control state reset)
			lea ntc_md_vregs, a0
			moveq #ntc_md_vregs_n-1, d0
ntc_mb_reg:
			move.w (a0)+, VDP_CTRL
			dbra d0, ntc_mb_reg
			move.l #$40000000, VDP_CTRL	; VRAM 0: all clear
			move.w #$8000-1, d0
ntc_mb_vram:
			move.w #0, VDP_DATA
			dbra d0, ntc_mb_vram
			move.l #$C0000000, VDP_CTRL	; CRAM
			moveq #64-1, d0
ntc_mb_cram:
			move.w #0, VDP_DATA
			dbra d0, ntc_mb_cram
			move.l #$40000010, VDP_CTRL	; VSRAM
			moveq #40-1, d0
ntc_mb_vsram:
			move.w #0, VDP_DATA
			dbra d0, ntc_mb_vsram
			move.l #$C0020000, VDP_CTRL	; palette 0 colour 1: the text, white
			move.w #$0EEE, VDP_DATA
			; the font: tiles 32-126 at $0400, 1 bit a pixel -> colour 1
			move.l #$44000000, VDP_CTRL
			lea ntc_md_font, a0
			move.w #95*8-1, d1
ntc_mb_font:
			move.b (a0)+, d2
			moveq #0, d3
			moveq #8-1, d4
ntc_mb_fbit:
			lsl.l #4, d3
			add.b d2, d2
			bcc ntc_mb_f0
			addq.b #1, d3
ntc_mb_f0:
			dbra d4, ntc_mb_fbit
			move.l d3, VDP_DATA
			dbra d1, ntc_mb_font
			move.w #$8174, VDP_CTRL		; the display on, the frame interrupt on
			; the pads: TH an output, high
			move.b #$40, $A10009
			move.b #$40, $A1000B
			move.b #$40, $A10003
			move.b #$40, $A10005
			; the PSG quiet
			move.b #$9F, PSG_PORT
			move.b #$BF, PSG_PORT
			move.b #$DF, PSG_PORT
			move.b #$FF, PSG_PORT
			move.b #40, ntc_scols
			move.b #28, ntc_srows
			move.l #NTC_USTACK, a0
			move.l a0, usp
			move.w #$0000, sr			; user mode, the interrupts on: A7 is now the user stack
			jmp ntc_start

ntc_md_vregs:
			dc.w $8004					; 0: no line interrupt
			dc.w $8134					; 1: display off for now, frame interrupt, DMA, 28 rows
			dc.w $8230					; 2: plane A at $C000
			dc.w $8328					; 3: the window at $A000
			dc.w $8407					; 4: plane B at $E000
			dc.w $856C					; 5: sprites at $D800
			dc.w $8600
			dc.w $8700					; 7: the backdrop: palette 0 colour 0
			dc.w $8800
			dc.w $8900
			dc.w $8AFF					; 10: line interrupt every 256 lines
			dc.w $8B00					; 11: whole screen scrolling
			dc.w $8C81					; 12: H40, no interlace
			dc.w $8D3F					; 13: horizontal scroll at $FC00
			dc.w $8E00
			dc.w $8F02					; 15: VDP address step 2
			dc.w $9001					; 16: planes 64 x 32 cells
			dc.w $9100					; 17, 18: no window
			dc.w $9200
ntc_md_vregs_n	equ (*-ntc_md_vregs)/2

; ------------------------------------------------------------
; interrupts and exceptions (supervisor mode, the supervisor stack)
; ------------------------------------------------------------
; the frame: count it, read the pads (3 or 6 button, once a frame - a 6
; button pad's counter needs the gap between reads), run the frame hook
ntc_md_vint:
			movem.l d0-d4/a0-a1, -(sp)
			addq.w #1, ntc_ticks
			addq.w #1, ntc_vbl
			lea $A10003, a0
			bsr ntc_md_pad
			move.w d0, ntc_pad1
			lea $A10005, a0
			bsr ntc_md_pad
			move.w d0, ntc_pad2
			move.l ntc_vhook, d0
			beq ntc_vi_nohook
			movea.l d0, a0
			jsr (a0)					; (keeps every register but d0-d4 / a0-a1)
ntc_vi_nohook:
			movem.l (sp)+, d0-d4/a0-a1
ntc_md_rte:
			rte
ntc_md_hint:
			rte

; a0 = the port's data register: d0 = its buttons (1 = held)
ntc_md_pad:
			move.b #$40, (a0)
			nop
			nop
			move.b (a0), d1				; ?1CBRLDU
			move.b #$00, (a0)
			nop
			nop
			move.b (a0), d2				; ?0SA00DU (TH's 2nd step)
			move.b #$40, (a0)
			nop
			nop
			move.b #$00, (a0)			; (4th: ?0SA00DU again)
			nop
			nop
			move.b #$40, (a0)
			nop
			nop
			move.b #$00, (a0)			; 6th: a 6 button pad says so here
			nop
			nop
			move.b (a0), d3				; ?0SA0000 on a 6 button pad
			move.b #$40, (a0)
			nop
			nop
			move.b (a0), d4				; ?1CBMXYZ on a 6 button pad (7th)
			move.b #$00, (a0)			; (8th: back to the start)
			nop
			nop
			move.b #$40, (a0)
			not.b d1
			not.b d2
			moveq #0, d0
			move.b d1, d0
			andi.b #$3F, d0				; Up Down Left Right B C
			lsl.b #2, d2
			andi.b #$C0, d2				; A, Start
			or.b d2, d0
			andi.b #$0F, d3
			bne ntc_mp_3b
			not.b d4
			andi.w #$0F, d4				; Z Y X Mode
			moveq #0, d1
			btst #2, d4
			beq ntc_mp_nx
			bset #8, d1					; X
ntc_mp_nx:
			btst #1, d4
			beq ntc_mp_ny
			bset #9, d1					; Y
ntc_mp_ny:
			btst #0, d4
			beq ntc_mp_nz
			bset #10, d1				; Z
ntc_mp_nz:
			btst #3, d4
			beq ntc_mp_nm
			bset #11, d1				; Mode
ntc_mp_nm:
			or.w d1, d0
ntc_mp_3b:
			rts

; an exception: its number and the PC on the console, then stop
ntc_md_ex2:	moveq #2, d7
			bra ntc_md_exg
ntc_md_ex3:	moveq #3, d7
ntc_md_exg:
			move.l 10(sp), d6			; bus / address error: the PC is further in
			bra ntc_md_exshow
ntc_md_ex4:	moveq #4, d7
			bra ntc_md_exn
ntc_md_ex5:	moveq #5, d7
			bra ntc_md_exn
ntc_md_ex6:	moveq #6, d7
			bra ntc_md_exn
ntc_md_ex7:	moveq #7, d7
			bra ntc_md_exn
ntc_md_ex8:	moveq #8, d7
			bra ntc_md_exn
ntc_md_ex9:	moveq #9, d7
			bra ntc_md_exn
ntc_md_ex10: moveq #10, d7
			bra ntc_md_exn
ntc_md_ex11: moveq #11, d7
			bra ntc_md_exn
ntc_md_exx:	moveq #0, d7
ntc_md_exn:
			move.l 2(sp), d6
ntc_md_exshow:
			move.w #$2700, sr
			move.l usp, a5				; the thread position
			jsr ntc_plat_newline
			lea ntc_md_extxt, a2
			bsr ntc_md_exstr
			move.l d7, d5
			moveq #2, d4
			bsr ntc_md_exhex
			lea ntc_md_expc, a2
			bsr ntc_md_exstr
			move.l d6, d5
			moveq #6, d4
			bsr ntc_md_exhex
			lea ntc_md_exsp, a2
			bsr ntc_md_exstr
			move.l a5, d5
			moveq #6, d4
			bsr ntc_md_exhex
ntc_md_exstop:
			bra ntc_md_exstop
ntc_md_exstr:
			moveq #0, d0
			move.b (a2)+, d0
			beq ntc_md_exse
			jsr ntc_plat_putc
			bra ntc_md_exstr
ntc_md_exse:
			rts
ntc_md_exhex:					; d5 = value, d4 = digits
			move.w d4, d3
			subq.w #1, d3
			lsl.w #2, d4
			ror.l d4, d5
ntc_md_exh1:
			rol.l #4, d5
			move.w d5, d0
			andi.w #$F, d0
			addi.b #'0', d0
			cmpi.b #'9'+1, d0
			bcs ntc_md_exh2
			addq.b #7, d0
ntc_md_exh2:
			jsr ntc_plat_putc
			dbra d3, ntc_md_exh1
			rts
ntc_md_extxt:	dc.b "68000 EXCEPTION ", 0
ntc_md_expc:	dc.b " PC ", 0
ntc_md_exsp:	dc.b " SP ", 0
			even

			even
;## ntc_md_vdp
; VDP helpers on the real stack (jsr): keep d2-d7 / a2-a6
; ntc_md_vaddr: d0.w = VRAM address -> VDP_CTRL set to write there
ntc_md_vaddr:
			move.l d1, -(sp)
			moveq #0, d1
			move.w d0, d1
			andi.w #$3FFF, d1
			ori.w #$4000, d1
			swap d1
			move.w d0, d1
			rol.w #2, d1
			andi.w #3, d1
			move.l d1, VDP_CTRL
			move.l (sp)+, d1
			rts

			even
;## ntc_plat_data

			even
;## ntc_plat_screen ntc_plat_data ntc_data ntc_md_vdp ntc_md_logs
; ntc_plat_putc - d0.b = character: on plane A at the cursor, move on, a new
; line after the last column. Real stack, keeps d2-d7 / a2-a6
ntc_plat_putc:
			movem.l d0-d2/a0, -(sp)
		ifd NTC_MDLOG
			bsr ntc_md_log
		endif
			moveq #0, d1
			move.b ntc_cury, d1
			mulu.w #40, d1
			moveq #0, d2
			move.b ntc_curx, d2
			add.w d2, d1
			lea ntc_shadow, a0
			move.b d0, 0(a0, d1.w)
			bsr ntc_md_cell			; d0 = char, the cursor's cell
			addq.b #1, ntc_curx
			move.b ntc_curx, d0
			cmp.b ntc_scols, d0
			bcs ntc_pc_nowrap
			move.b #1, ntc_wrapped
			movem.l (sp)+, d0-d2/a0
			bra ntc_nl_do
ntc_pc_nowrap:
			clr.b ntc_wrapped
			movem.l (sp)+, d0-d2/a0
			rts

; the cell at the cursor gets character d0 (VRAM: plane A, 64 cells a row)
ntc_md_cell:
			movem.l d0-d1, -(sp)
			moveq #0, d1
			move.b ntc_cury, d1
			lsl.w #6, d1
			moveq #0, d0
			move.b ntc_curx, d0
			add.w d0, d1
			add.w d1, d1
			addi.w #$C000, d1
			move.w d1, d0
			bsr ntc_md_vaddr
			movem.l (sp)+, d0-d1
			move.l d1, -(sp)
			moveq #0, d1
			move.b ntc_tattr, d1
			lsl.w #8, d1
			move.b d0, d1
			add.w ntc_tbase, d1
			move.w d1, VDP_DATA
			move.l (sp)+, d1
			rts

; ntc_plat_newline - column 0, next row (scrolls at the bottom); nothing straight after a wrap
ntc_plat_newline:
		ifd NTC_MDLOG
			move.l d0, -(sp)
			moveq #10, d0
			bsr ntc_md_log
			move.l (sp)+, d0
		endif
			tst.b ntc_wrapped
			beq ntc_nl_do
			clr.b ntc_wrapped
			rts
ntc_nl_do:
			clr.b ntc_curx
			addq.b #1, ntc_cury
			move.b ntc_cury, d0
			cmp.b ntc_srows, d0
			bcs ntc_nl_e
			subq.b #1, ntc_cury
			bra ntc_md_scroll
ntc_nl_e:
			rts

; the text up a row: the shadow moved up, the last row cleared, plane A redrawn
ntc_md_scroll:
			movem.l d0-d3/a0-a1, -(sp)
			lea ntc_shadow, a0
			lea 40(a0), a1
			move.w #40*27-1, d0
ntc_sc_mv:
			move.b (a1)+, (a0)+
			dbra d0, ntc_sc_mv
			moveq #40-1, d0
ntc_sc_cl:
			move.b #' ', (a0)+
			dbra d0, ntc_sc_cl
			bsr ntc_md_redraw
			movem.l (sp)+, d0-d3/a0-a1
			rts

; plane A from the shadow (28 rows of 40)
ntc_md_redraw:
			movem.l d0-d3/a0, -(sp)
			lea ntc_shadow, a0
			moveq #0, d2				; row
			moveq #0, d3
			move.b ntc_tattr, d3
			lsl.w #8, d3
ntc_rd_row:
			move.w d2, d0
			lsl.w #7, d0
			addi.w #$C000, d0
			bsr ntc_md_vaddr
			moveq #40-1, d1
ntc_rd_col:
			moveq #0, d0
			move.b (a0)+, d0
			bne ntc_rd_ch
			moveq #' ', d0
ntc_rd_ch:
			or.w d3, d0
			add.w ntc_tbase, d0
			move.w d0, VDP_DATA
			dbra d1, ntc_rd_col
			addq.w #1, d2
			cmpi.w #28, d2
			bcs ntc_rd_row
			movem.l (sp)+, d0-d3/a0
			rts

			even
;## ntc_plat_cls @unit ntc_plat_screen ntc_plat_data ntc_data
; ntc_plat_cls - clear the console, the cursor home
ntc_plat_cls:
			movem.l d0/a0, -(sp)
			lea ntc_shadow, a0
			move.w #40*28-1, d0
ntc_cls_lp:
			move.b #' ', (a0)+
			dbra d0, ntc_cls_lp
			clr.b ntc_curx
			clr.b ntc_cury
			clr.b ntc_wrapped
			bsr ntc_md_redraw
			movem.l (sp)+, d0/a0
			rts

			even
;## ntc_md_logs
		ifd NTC_MDLOG
; test builds (vasm -DNTC_MDLOG): what the console was given, at $FF0000 on (the
; harness reads it): characters, 10 for a new line. $FF6FFC: where the next goes
ntc_md_log:
			move.l a0, -(sp)
			movea.l $FF6FFC, a0
			cmpa.l #$FF0000, a0
			bcc ntc_lg_ok
			lea $FF0000, a0
ntc_lg_ok:
			cmpa.l #$FF6FF0, a0
			bcc ntc_lg_full
			move.b d0, (a0)+
			move.l a0, $FF6FFC
ntc_lg_full:
			movea.l (sp)+, a0
			rts
		endif

			even
;## ntc_plat_key ntc_data ntc_plat_data ntc_plat_frame
; ntc_plat_scankey - d0 = the code of a button newly pressed on pad 1, or 0
ntc_plat_scankey:
			movem.l d1-d2/a0, -(sp)
			move.w ntc_pad1, d1
			move.w ntc_padseen, d2
			move.w d1, ntc_padseen
			not.w d2
			and.w d2, d1				; the new ones
			moveq #0, d0
			lea ntc_md_keys, a0
			moveq #0, d2
ntc_sk_lp:
			btst d2, d1
			bne ntc_sk_got
			addq.w #1, d2
			cmpi.w #12, d2
			bcs ntc_sk_lp
			bra ntc_sk_e
ntc_sk_got:
			move.b 0(a0, d2.w), d0
ntc_sk_e:
			movem.l (sp)+, d1-d2/a0
			rts
ntc_md_keys:	dc.b $F0, $F1, $F2, $F3, 'B', 'C', 'A', 13, 'X', 'Y', 'Z', 27
			even

; ntc_plat_getkey - wait for a button: d0 = its code
ntc_plat_getkey:
			bsr ntc_plat_scankey
			tst.b d0
			bne ntc_gk_e
			bsr ntc_plat_frame
			bra ntc_plat_getkey
ntc_gk_e:
			rts

			even
;## ntc_plat_frame ntc_plat_data
; ntc_plat_frame - wait for the next frame interrupt (the start of the vertical blank)
ntc_plat_frame:
			move.l d0, -(sp)
			move.w ntc_vbl, d0
ntc_fr_lp:
			cmp.w ntc_vbl, d0
			beq ntc_fr_lp
			move.l (sp)+, d0
			rts

			even
;## ntc_plat_exit ntc_plat_data
; ntc_plat_exit - before the program stops: nothing to give back on a Mega Drive
ntc_plat_exit:
			rts

			even
