var_bad:			dc.w 0
p_chkl_rs:			dc.l 0
var_chkl_got:			dc.l 0
var_chkl_want:			dc.l 0
p_chk_rs:			dc.l 0
var_chk_got:			dc.w 0
var_chk_want:			dc.w 0
